const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function sanitizeRich(input=''){let html=String(input).slice(0,300000).replace(/<(script|style|iframe|object|embed|svg|math|form)\b[^>]*>[\s\S]*?<\/\1\s*>/gi,'').replace(/<!--([\s\S]*?)-->/g,'');const allowed=new Set(['p','br','h1','h2','h3','strong','b','em','i','u','s','ul','ol','li','blockquote','a','table','thead','tbody','tr','td','th','hr','span','img']);html=html.replace(/<\/?([a-z0-9]+)\b([^>]*)>/gi,(all,name,attrs)=>{const tag=name.toLowerCase();if(!allowed.has(tag))return '';const closing=all.startsWith('</');if(closing)return `</${tag}>`;if(tag==='a'){const href=attrs.match(/\bhref\s*=\s*(["'])(.*?)\1/i)?.[2]||'';return /^https?:\/\//i.test(href.trim())?`<a href="${escapeHtml(href)}" rel="nofollow noopener">`:'<a>';}if(tag==='img'){const src=attrs.match(/\bsrc\s*=\s*(["'])(.*?)\1/i)?.[2]||'',alt=attrs.match(/\balt\s*=\s*(["'])(.*?)\1/i)?.[2]||'';return /^\/api\/editor-images\?id=[\w-]+(?:&amp;|&)projectId=[\w-]+$/.test(src)?`<img src="${escapeHtml(src)}" alt="${escapeHtml(alt)}">`:'';}if(tag==='span'){const style=attrs.match(/\bstyle\s*=\s*(["'])(.*?)\1/i)?.[2]||'',color=style.match(/(?:^|;)\s*color\s*:\s*(#[0-9a-f]{3,8})\s*(?:;|$)/i)?.[1],bg=style.match(/(?:^|;)\s*background-color\s*:\s*(#[0-9a-f]{3,8})\s*(?:;|$)/i)?.[1];const safe=[color&&`color:${color}`,bg&&`background-color:${bg}`].filter(Boolean).join(';');return safe?`<span style="${safe}">`:'<span>';}if(tag==='ul'&&/\bdata-checklist\s*=\s*(["'])true\1/i.test(attrs))return '<ul data-checklist="true">';if(tag==='li'&&/\bdata-checked\s*=\s*(["'])true\1/i.test(attrs))return '<li data-checked="true">';if(tag==='li'&&/\bdata-checked\s*=\s*(["'])false\1/i.test(attrs))return '<li data-checked="false">';return `<${tag}>`;});return html;}
function generatedAvatar(name,id){const seed=createHash('sha256').update(String(id)).digest(),hue=seed.readUInt16BE(0)%360,initial=Array.from(String(name||'用户').trim()).slice(-1)[0]||'用',glyph=initial.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c])),svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 128"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="hsl(${hue} 66% 61%)"/><stop offset="1" stop-color="hsl(${(hue+42)%360} 58% 43%)"/></linearGradient></defs><rect width="128" height="128" rx="64" fill="url(#g)"/><circle cx="100" cy="28" r="18" fill="#fff" opacity=".16"/><text x="64" y="82" text-anchor="middle" font-family="Arial,sans-serif" font-size="58" font-weight="700" fill="#fff">${glyph}</text></svg>`;return `data:image/svg+xml;base64,${Buffer.from(svg).toString('base64')}`;}
