function bindDocumentImages(workspace,html,type,recordId,userId){const ids=[...new Set([...String(html).matchAll(/\/api\/editor-images\?id=([\w-]+)/g)].map(x=>x[1]))];if(ids.length>30)return false;const records=ids.map(id=>(workspace.files||[]).find(f=>f.kind==='正文图片'&&f.id===id));if(records.some(f=>!f||f.documentType!==type||(f.documentId!==recordId&&f.uploaderId!==userId)))return false;for(const f of records){f.documentId=recordId;f.savedAt=new Date().toISOString()}return true;}
