const runBackup=payload=>new Promise((resolve,reject)=>{const child=spawn(process.platform==='win32'?'python':'python3',[path.join(root,'scripts','backup_project.py')],{stdio:['pipe','pipe','pipe']});const chunks=[],errors=[];child.stdout.on('data',x=>chunks.push(x));child.stderr.on('data',x=>errors.push(x));child.on('error',reject);child.on('close',code=>{if(code!==0)return reject(new Error(Buffer.concat(chunks).toString('utf8')||Buffer.concat(errors).toString('utf8')||'备份处理失败。'));try{resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')))}catch{reject(new Error('备份工具返回了无效数据。'))}});child.stdin.end(JSON.stringify(payload));});
let saveQueue=Promise.resolve();const save=()=>{const snapshot=JSON.stringify(database,null,2),temp=`${dataFile}.${randomUUID()}.tmp`;const write=()=>writeFile(temp,snapshot).then(()=>rename(temp,dataFile));saveQueue=saveQueue.then(write,write);return saveQueue;};

