      if(req.method==='POST'&&url.pathname==='/api/register'){const b=await body(req),account=String(b.account||'').trim(),name=String(b.name||'').trim(),password=String(b.password||'');if(!/^[A-Za-z0-9_]{4,30}$/.test(account)||!name||name.length>20||password.length<6||password.length>32||b.confirmPassword!==password)return json(res,400,{error:'请填写有效账号、姓名和密码，并确认两次密码一致。'});if(database.accounts.some(x=>x.account.toLowerCase()===account.toLowerCase()))return json(res,409,{error:'该账号已注册。'});const salt=randomBytes(16).toString('hex'),id=randomUUID();database.accounts.push({id,name,account,salt,password:hashPassword(password,salt),avatar:generatedAvatar(name,id),avatarMode:'default'});await save();return json(res,201,{id,name,message:'账号已创建，请登录后创建项目或接受邀请。'});}
