      if(req.method==='GET'&&url.pathname==='/api/me')return json(res,200,actor);
      if(req.method==='PATCH'&&url.pathname==='/api/profile'){const b=await body(req),name=String(b.name||'').trim(),accountName=String(b.account||'').trim();if(!name||name.length>20||!/^[A-Za-z0-9_]{4,30}$/.test(accountName))return json(res,400,{error:'显示名称需为1至20字，登录账号需为4至30位字母、数字或下划线。'});if(database.accounts.some(x=>x.id!==actor.id&&x.account.toLowerCase()===accountName.toLowerCase()))return json(res,409,{error:'该登录账号已被使用。'});const account=database.accounts.find(x=>x.id===actor.id);if(!account)return json(res,404,{error:'账号不存在。'});const previous=account.name;account.name=name;account.account=accountName;if(account.avatarMode==='default')account.avatar=generatedAvatar(name,actor.id);for(const workspace of database.workspaces){const person=workspace.people.find(x=>x.id===actor.id);if(!person)continue;person.name=name;if(workspace.project.status==='已归档')continue;for(const m of workspace.meetings){if(m.hostId===actor.id)m.host=name;if(m.organizerId===actor.id)m.organizer=name;if(Array.isArray(m.attendeeIds))m.attendees=m.attendeeIds.map(id=>workspace.people.find(x=>x.id===id)?.name||'');if(Array.isArray(m.checkedIds))m.checked=m.checkedIds.map(id=>workspace.people.find(x=>x.id===id)?.name||'');for(const item of m.attendance||[])if(item.personId===actor.id)item.name=name;for(const item of m.supplements||[]){if(item.personId===actor.id)item.name=name;if(item.operatorId===actor.id){item.by=name;item.operator=name}}}for(const a of workspace.assignments){if(a.ownerId===actor.id)a.owner=name;if(a.byId===actor.id)a.by=name}for(const l of workspace.logs)if(l.authorId===actor.id)l.author=name;for(const f of workspace.files||[])if(f.uploadedById===actor.id)f.uploadedBy=name;}await save();return json(res,200,{id:actor.id,name,account:accountName,avatar:account.avatar||'',previousName:previous});}
